// Chequea que quien califica sea el cliente de ese trabajo, y arma el texto
const ev    = $('Llega una calificacion').first().json.body || {};
const quien = $('Verificar quien pide').first().json;

if (!quien || !quien.id) {
  return [{ json: { ok:false, motivo:'sesion' } }];
}

// n8n parte las listas en items: los juntamos de nuevo
function juntar(nodo) {
  try {
    const items = $(nodo).all().map(i => i.json);
    return items.flat().filter(x => x && typeof x === 'object');
  } catch (e) { return []; }
}

const m = juntar('Traer el match')[0];
if (!m || !m.solicitudes || !m.proveedores) {
  return [{ json: { ok:false, motivo:'match' } }];
}

// solo el cliente dueño del pedido puede calificar
if (m.solicitudes.user_id !== quien.id) {
  return [{ json: { ok:false, motivo:'permiso' } }];
}

const msgs = juntar('Traer la conversacion');
// Alcanza con dos mensajes o con un presupuesto aceptado: la app ofrece
// calificar apenas se acepta, y ahí la charla puede ser solo el presupuesto.
const aceptado = msgs.some(x => x.tipo === 'presupuesto' && x.estado_presupuesto === 'aceptado');
if (msgs.length < 2 && !aceptado) {
  return [{ json: { ok:false, motivo:'corta' } }];
}

// medimos el tiempo de respuesta del proveedor, que es dato duro
let sumas = 0, veces = 0, ultimoCliente = null;
msgs.forEach(x => {
  if (x.remitente_tipo === 'cliente') ultimoCliente = new Date(x.created_at);
  else if (ultimoCliente) {
    sumas += (new Date(x.created_at) - ultimoCliente) / 60000;
    veces++; ultimoCliente = null;
  }
});
const minutos = veces ? Math.round(sumas / veces) : null;

const charla = msgs.map(x => {
  const quienEs = x.remitente_tipo === 'cliente' ? 'CLIENTE' : 'PROVEEDOR';
  if (x.tipo === 'presupuesto') return `${quienEs} [envió un presupuesto formal]`;
  return `${quienEs}: ${String(x.contenido || '').slice(0, 400)}`;
}).join('\n').slice(0, 6000);

return [{ json: {
  ok: true,
  charla,
  minutos,
  matchId: ev.matchId,
  puntaje: Math.min(5, Math.max(1, Number(ev.puntaje) || 5)),
  comentario: String(ev.comentario || '').slice(0, 400),
  proveedorUserId: m.proveedores.user_id,
  clienteUserId: quien.id
} }];

