const ctx = $('Validar y armar').first().json;
if (!ctx.ok) return [{ json: ctx }];

let r = {};
try {
  r = JSON.parse($input.first().json.choices[0].message.content.replace(/```json|```/g,'').trim());
} catch(e) { r = { atributos: [], resumen: '' }; }

let atributos = Array.isArray(r.atributos) ? r.atributos.slice(0,3).map(String) : [];
// el tiempo de respuesta lo medimos nosotros, no lo dejamos al criterio de la IA
if (ctx.minutos !== null && ctx.minutos <= 30 && !atributos.includes('Responde rápido')) {
  atributos.unshift('Responde rápido');
  atributos = atributos.slice(0,3);
}

return [{ json: {
  ok: true,
  matchId: ctx.matchId,
  proveedorUserId: ctx.proveedorUserId,
  clienteUserId: ctx.clienteUserId,
  puntaje: ctx.puntaje,
  comentario: ctx.comentario,
  atributos,
  resumen: String(r.resumen || '').slice(0,200)
} }];
